@page "/"
@using RecipeHub.Services

<PageTitle>RecipeHub - Share & Discover Recipes</PageTitle>

<div class="container">
    <div class="text-center my-5">
        <h1 class="display-4">🍳 RecipeHub</h1>
        <p class="lead text-muted">Discover, share, and rate recipes from around the world</p>
    </div>

    <h2 class="mb-4">Browse by Category</h2>
    <div class="row">
        @foreach (var category in categories)
        {
            <div class="col-md-4 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body text-center">
                        <span class="display-3">@category.Icon</span>
                        <h5 class="card-title mt-3">@category.Name</h5>
